<?php
/** 2026-11-04. Flujo comercial auditado; utiliza el PDO compartido de Mysql. */
class PedRevisionService extends Mysql {
 private function run(string $sql,array $args=[]):PDOStatement {$s=$this->getConexion()->prepare($sql);$s->execute($args);return $s;}
 private function row(string $sql,array $args=[]):?array {return $this->run($sql,$args)->fetch(PDO::FETCH_ASSOC)?:null;}
 private function rows(string $sql,array $args=[]):array {return $this->run($sql,$args)->fetchAll(PDO::FETCH_ASSOC);}
 private function evento(int $p,string $tipo,string $desc,int $u,string $antes='',string $nuevo='',int $origen=1):void {
  $this->run('INSERT INTO ped_bitacora_eventos(idpedido,tipo_evento,descripcion,estatus_anterior,estatus_nuevo,usuario_registro,origen,fecha_creacion,fecha_actualizacion) VALUES(?,?,?,?,?,?,?,NOW(),NOW())',[$p,$tipo,$desc,$antes,$nuevo,$u,$origen]);
 }
 public function pedido(string $clave):?array{return $this->row('SELECT * FROM ped_pedidos WHERE clave=? AND estado=2',[$clave]);}
 public function ultima(int $p):?array{return $this->row('SELECT * FROM ped_pedidos_revisiones WHERE idpedido=? ORDER BY numero_revision DESC LIMIT 1',[$p]);}
 public function versiones(int $p):array{return $this->rows('SELECT * FROM ped_pedidos_revisiones WHERE idpedido=? ORDER BY numero_revision DESC',[$p]);}
 public function lineas(int $r):array{return $this->rows('SELECT d.*,u.nombre,u.modelo,u.version,co.nombre AS nombre_color,cor.nombre AS nombre_color_original FROM ped_pedidos_revision_detalle d JOIN web_unidades u ON u.idunidad=d.idunidad LEFT JOIN web_unidades_colores uc ON uc.idunidad_color=d.idunidad_color LEFT JOIN web_colores co ON co.idcolor=uc.idcolor LEFT JOIN web_unidades_colores uco ON uco.idunidad_color=d.idunidad_color_original LEFT JOIN web_colores cor ON cor.idcolor=uco.idcolor WHERE d.idrevision=? ORDER BY d.orden,d.idrevision_detalle',[$r]);}
 public function respuestas(int $pedido):array{return $this->rows('SELECT r.numero_revision,rr.respuesta,rr.observaciones,rr.fecha_respuesta,rr.idusuario_acceso,CONCAT_WS(" ",ua.nombre,ua.apellido) AS nombre_responsable FROM ped_pedidos_revision_respuestas rr JOIN ped_pedidos_revisiones r ON r.idrevision=rr.idrevision LEFT JOIN cli_usuarios_acceso ua ON ua.idusuario_acceso=rr.idusuario_acceso WHERE rr.idpedido=? ORDER BY rr.fecha_respuesta DESC,rr.idrespuesta DESC',[$pedido]);}
 public function colores(int $unidad):array{return $this->rows('SELECT uc.idunidad_color,c.nombre FROM web_unidades_colores uc JOIN web_colores c ON c.idcolor=uc.idcolor WHERE uc.idunidad=? AND uc.estado=2 AND c.estado=2 ORDER BY uc.orden',[$unidad]);}
 public function backorders(int $p):array{return $this->rows("SELECT b.*,u.modelo,c.nombre AS nombre_color,COALESCE(NULLIF(rd.tipo_entrega,''),pd.tipo_entrega) AS tipo_entrega,COALESCE(rd.idsucursal_entrega,pd.idsucursal_entrega) AS idsucursal_entrega,COALESCE(NULLIF(rd.direccion_entrega,''),pd.direccion_entrega) AS direccion_entrega,suc.nombre_sucursal AS sucursal_entrega FROM ped_backorder b JOIN web_unidades u ON u.idunidad=b.idunidad LEFT JOIN ped_pedidos_revision_detalle rd ON rd.idrevision_detalle=b.idrevision_detalle LEFT JOIN ped_pedidos_detalle pd ON pd.idpedido_detalle=COALESCE(b.idpedido_detalle,rd.idpedido_detalle_origen) LEFT JOIN cli_clientes_sucursales suc ON suc.idsucursal=COALESCE(rd.idsucursal_entrega,pd.idsucursal_entrega) LEFT JOIN web_unidades_colores uc ON uc.idunidad_color=b.idunidad_color LEFT JOIN web_colores c ON c.idcolor=uc.idcolor WHERE b.idpedido=? ORDER BY b.idbackorder",[$p]);}
 private function transaction(callable $callback){$db=$this->getConexion();$db->beginTransaction();try{$result=$callback();$db->commit();return $result;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
 private function locked(string $clave):array{$p=$this->row('SELECT * FROM ped_pedidos WHERE clave=? AND estado=2 FOR UPDATE',[$clave]);if(!$p||$p['estatus']!=='EN_REVISION')throw new RuntimeException('El pedido no está en revisión comercial.');return $p;}
 private function totales(int $id):void{$this->run('UPDATE ped_pedidos_revisiones SET subtotal=(SELECT COALESCE(SUM(subtotal),0) FROM ped_pedidos_revision_detalle WHERE idrevision=?),descuento=(SELECT COALESCE(SUM(descuento),0) FROM ped_pedidos_revision_detalle WHERE idrevision=?),iva=(SELECT COALESCE(SUM(iva),0) FROM ped_pedidos_revision_detalle WHERE idrevision=?),total=(SELECT COALESCE(SUM(total),0) FROM ped_pedidos_revision_detalle WHERE idrevision=?) WHERE idrevision=?',[$id,$id,$id,$id,$id]);}
 public function crear(string $clave,int $usuario):array{return $this->transaction(function()use($clave,$usuario){
  $p=$this->locked($clave);$r=$this->ultima((int)$p['idpedido']);
  if($r&&$r['estatus']==='BORRADOR')return $r;
  if($r&&$r['estatus']!=='AJUSTE_SOLICITADO')throw new RuntimeException('La versión actual no permite crear otro borrador.');
  $n=$r?(int)$r['numero_revision']+1:1;
  $this->run("INSERT INTO ped_pedidos_revisiones(idpedido,numero_revision,revision_origen_id,estatus,creado_por) VALUES(?,?,?,'BORRADOR',?)",[$p['idpedido'],$n,$r['idrevision']??null,$usuario]);$id=(int)$this->getConexion()->lastInsertId();
  if($r){$this->run('INSERT INTO ped_pedidos_revision_detalle(idrevision,idpedido_detalle_origen,tipo_cambio,idunidad,idunidad_color_original,idunidad_color,cantidad_solicitada_original,cantidad_propuesta,tipo_entrega,idsucursal_entrega,direccion_entrega,precio_unitario_original,precio_unitario,descuento,descuento_tipo,descuento_valor,subtotal,iva,total,motivo_ajuste,orden) SELECT ?,idpedido_detalle_origen,tipo_cambio,idunidad,idunidad_color_original,idunidad_color,cantidad_solicitada_original,cantidad_propuesta,tipo_entrega,idsucursal_entrega,direccion_entrega,precio_unitario_original,precio_unitario,descuento,descuento_tipo,descuento_valor,subtotal,iva,total,motivo_ajuste,orden FROM ped_pedidos_revision_detalle WHERE idrevision=?',[$id,$r['idrevision']]);}
  else {$this->run("INSERT INTO ped_pedidos_revision_detalle(idrevision,idpedido_detalle_origen,tipo_cambio,idunidad,idunidad_color_original,idunidad_color,cantidad_solicitada_original,cantidad_propuesta,tipo_entrega,idsucursal_entrega,direccion_entrega,precio_unitario_original,precio_unitario,descuento,descuento_tipo,descuento_valor,subtotal,iva,total,orden) SELECT ?,idpedido_detalle,'SIN_CAMBIO',idunidad,idunidad_color,idunidad_color,cantidad_solicitada,cantidad_solicitada,tipo_entrega,idsucursal_entrega,direccion_entrega,precio_unitario,precio_unitario,descuento,'MONTO',descuento,subtotal,iva,total,idpedido_detalle FROM ped_pedidos_detalle WHERE idpedido=? AND estado=2",[$id,$p['idpedido']]);}
  $this->totales($id);$this->evento((int)$p['idpedido'],'REVISION_CREADA','Borrador de propuesta v'.$n,$usuario,'','BORRADOR');return $this->ultima((int)$p['idpedido']);
 });}
 public function guardar(string $clave,int $usuario,array $lineas,string $nota):array{return $this->transaction(function()use($clave,$usuario,$lineas,$nota){
  $p=$this->locked($clave);$r=$this->ultima((int)$p['idpedido']);if(!$r||$r['estatus']!=='BORRADOR')throw new RuntimeException('No hay borrador editable.');
  $actual=$this->rows('SELECT rd.*, od.descuento AS descuento_original FROM ped_pedidos_revision_detalle rd LEFT JOIN ped_pedidos_detalle od ON od.idpedido_detalle=rd.idpedido_detalle_origen WHERE rd.idrevision=? FOR UPDATE',[$r['idrevision']]);$map=[];foreach($actual as $x)$map[(int)$x['idrevision_detalle']]=$x;
  if(!$lineas||count($lineas)!==count($map))throw new RuntimeException('Recarga los renglones de la revisión.');$seen=[];
  $base=(float)$p['subtotal']-(float)$p['descuento'];$tasa=$base>0?(float)$p['iva']/$base:0.16;if($tasa<0||$tasa>0.3)throw new RuntimeException('Revisar IVA original del pedido.');
  foreach($lineas as $v){$id=(int)($v['idrevision_detalle']??0);if(!isset($map[$id])||isset($seen[$id]))throw new RuntimeException('Renglón inválido.');$seen[$id]=true;$x=$map[$id];
   $qty=filter_var($v['cantidad_propuesta']??null,FILTER_VALIDATE_INT);$pr=$v['precio_unitario']??null;$ds=$v['descuento_valor']??($v['descuento']??null);$tipo=(string)($v['descuento_tipo']??'MONTO');
   if(!in_array($tipo,['MONTO','PORCENTAJE'],true)||$qty===false||$qty<0||$qty>100000||!is_numeric($pr)||!is_numeric($ds)||(float)$pr<0||(float)$pr>999999999||(float)$ds<0)throw new RuntimeException('Valores fuera de rango.');
   $color=($v['idunidad_color']??'')===''?null:(int)$v['idunidad_color'];if($color===null && $x['idunidad_color_original']!==null)throw new RuntimeException('El color seleccionado originalmente no puede quedar vacío.');if($color!==null&&!$this->row('SELECT idunidad_color FROM web_unidades_colores WHERE idunidad_color=? AND idunidad=? AND estado=2',[$color,$x['idunidad']]))throw new RuntimeException('Color no disponible para el modelo.');
   $pr=round((float)$pr,2);$valor=round((float)$ds,2);$sub=round($pr*$qty,2);if($tipo==='PORCENTAJE'&&$valor>100)throw new RuntimeException('El porcentaje no puede superar el 100%.');$ds=$tipo==='PORCENTAJE'?round($sub*$valor/100,2):$valor;if($ds>$sub)throw new RuntimeException('Descuento mayor al subtotal.');$iva=round(($sub-$ds)*$tasa,2);$total=round($sub-$ds+$iva,2);
   $cambio=($qty!=(int)$x['cantidad_solicitada_original']||$color!==($x['idunidad_color_original']===null?null:(int)$x['idunidad_color_original'])||$pr!=(float)$x['precio_unitario_original']||$ds!=(float)($x['descuento_original']??0))?'MODIFICADO':'SIN_CAMBIO';
   $motivo=trim((string)($v['motivo_ajuste']??''));if($cambio==='MODIFICADO'&&$motivo==='')throw new RuntimeException('Escribe el motivo de cada cambio.');
   $this->run('UPDATE ped_pedidos_revision_detalle SET tipo_cambio=?,idunidad_color=?,cantidad_propuesta=?,precio_unitario=?,descuento=?,descuento_tipo=?,descuento_valor=?,subtotal=?,iva=?,total=?,motivo_ajuste=? WHERE idrevision_detalle=? AND idrevision=?',[$cambio,$color,$qty,$pr,$ds,$tipo,$valor,$sub,$iva,$total,mb_substr($motivo,0,3000),$id,$r['idrevision']]);
  }
  $this->totales((int)$r['idrevision']);$this->run('UPDATE ped_pedidos_revisiones SET observaciones_comercial=?,fecha_actualizacion=NOW() WHERE idrevision=?',[mb_substr($nota,0,5000),$r['idrevision']]);
  $this->evento((int)$p['idpedido'],'REVISION_GUARDADA','Actualización de borrador v'.$r['numero_revision'],$usuario,'BORRADOR','BORRADOR');return $this->ultima((int)$p['idpedido']);
 });}
 public function enviar(string $clave,int $usuario):array{return $this->transaction(function()use($clave,$usuario){
  $p=$this->locked($clave);$r=$this->ultima((int)$p['idpedido']);if(!$r||$r['estatus']!=='BORRADOR')throw new RuntimeException('No hay borrador para enviar.');
  $lineas=$this->lineas((int)$r['idrevision']);if(array_sum(array_column($lineas,'cantidad_propuesta'))<=0)throw new RuntimeException('La propuesta debe incluir unidades.');
  $this->run("UPDATE ped_pedidos_revisiones SET estatus='PENDIENTE_ACEPTACION',enviado_por=?,fecha_envio=NOW() WHERE idrevision=?",[$usuario,$r['idrevision']]);
  $this->run("UPDATE ped_pedidos SET estatus_revision_comercial='PENDIENTE_ACEPTACION',fecha_actualizacion=NOW() WHERE idpedido=?",[$p['idpedido']]);
  $this->evento((int)$p['idpedido'],'PROPUESTA_ENVIADA','Enviada propuesta v'.$r['numero_revision'],$usuario,'EN_REVISION','PENDIENTE_ACEPTACION');return $this->ultima((int)$p['idpedido']);
 });}
 private function huella(array $r,array $d):string{$v=['revision'=>$r['idrevision'],'total'=>$r['total'],'detalles'=>[]];foreach($d as $x)$v['detalles'][]=[$x['idrevision_detalle'],$x['idunidad'],$x['idunidad_color'],$x['cantidad_propuesta'],$x['precio_unitario'],$x['descuento'],$x['descuento_tipo']??'MONTO',$x['descuento_valor']??$x['descuento'],$x['subtotal'],$x['iva'],$x['total']];return hash('sha256',json_encode($v,JSON_UNESCAPED_UNICODE));}
 public function responder(string $clave,int $cliente,int $usuario,string $accion,string $nota,string $ip,string $agente):array{return $this->transaction(function()use($clave,$cliente,$usuario,$accion,$nota,$ip,$agente){
  if(!in_array($accion,['ACEPTAR','SOLICITAR_AJUSTE','RECHAZAR'],true))throw new RuntimeException('Respuesta inválida.');if(in_array($accion,['SOLICITAR_AJUSTE','RECHAZAR'],true)&&mb_strlen(trim($nota))<5)throw new RuntimeException('Describe el ajuste solicitado.');
  $p=$this->row('SELECT * FROM ped_pedidos WHERE clave=? AND idcliente=? AND estado=2 FOR UPDATE',[$clave,$cliente]);if(!$p||$p['estatus']!=='EN_REVISION')throw new RuntimeException('Pedido no disponible.');
  $r=$this->row('SELECT * FROM ped_pedidos_revisiones WHERE idpedido=? ORDER BY numero_revision DESC LIMIT 1 FOR UPDATE',[(int)$p['idpedido']]);if(!$r||$r['estatus']!=='PENDIENTE_ACEPTACION')throw new RuntimeException('Esta propuesta ya fue atendida.');$d=$this->lineas((int)$r['idrevision']);if(!$d)throw new RuntimeException('Propuesta sin renglones.');
  $this->run('INSERT INTO ped_pedidos_revision_respuestas(idrevision,idpedido,idusuario_acceso,respuesta,observaciones,hash_contenido_revision,ip_origen,agente_usuario) VALUES(?,?,?,?,?,?,?,?)',[$r['idrevision'],$p['idpedido'],$usuario,$accion,mb_substr($nota,0,5000),$this->huella($r,$d),mb_substr($ip,0,45),mb_substr($agente,0,500)]);
  $acepta=$accion==='ACEPTAR';$estado=$acepta?'ACEPTADA':($accion==='RECHAZAR'?'RECHAZADA':'AJUSTE_SOLICITADO');$this->run('UPDATE ped_pedidos_revisiones SET estatus=?,fecha_respuesta=NOW() WHERE idrevision=?',[$estado,$r['idrevision']]);
  $this->run('UPDATE ped_pedidos SET estatus_revision_comercial=?,fecha_actualizacion=NOW() WHERE idpedido=?',[$estado,$p['idpedido']]);
  if($accion==='RECHAZAR'){$this->run("UPDATE ped_pedidos SET estatus='RECHAZADO',version=version+1,fecha_actualizacion=NOW() WHERE idpedido=?",[$p['idpedido']]);}
  if($acepta){foreach($d as $x){$cantidad=(int)$x['cantidad_propuesta'];if($cantidad===0)continue;
   $this->run("INSERT INTO ped_backorder(idpedido,idrevision_detalle,idpedido_detalle,origen,idunidad,idunidad_color,cantidad_comprometida,cantidad_atendida_inicial,cantidad_asignada,cantidad_pendiente,precio_unitario,descuento,subtotal,iva,total,estatus,creado_por) VALUES(?,?,?,'ACEPTACION_PORTAL',?,?,?,0,0,?,?,?,?,?,?,'PENDIENTE',?)",[$p['idpedido'],$x['idrevision_detalle'],$x['idpedido_detalle_origen'],$x['idunidad'],$x['idunidad_color'],$cantidad,$cantidad,$x['precio_unitario'],$x['descuento'],$x['subtotal'],$x['iva'],$x['total'],$usuario]);
   $id=(int)$this->getConexion()->lastInsertId();$this->run("INSERT INTO ped_backorder_movimientos(idbackorder,tipo_movimiento,cantidad_delta_pendiente,cantidad_pendiente_anterior,cantidad_pendiente_nueva,referencia_tipo,referencia_id,motivo,usuario_registro) VALUES(?,'ALTA',?,0,?,'REVISION',?,'Aceptación del distribuidor',?)",[$id,$cantidad,$cantidad,$r['idrevision'],$usuario]);
  }$this->run("UPDATE ped_pedidos SET estatus='BACK_ORDER',version=version+1,fecha_actualizacion=NOW() WHERE idpedido=?",[$p['idpedido']]);}
  $this->evento((int)$p['idpedido'],$acepta?'PROPUESTA_ACEPTADA':($accion==='RECHAZAR'?'PROPUESTA_RECHAZADA':'AJUSTE_SOLICITADO'),'Respuesta a propuesta v'.$r['numero_revision'].' por usuario de portal #'.$usuario.': '.mb_substr($nota?:'Sin observaciones',0,400),$usuario,'PENDIENTE_ACEPTACION',$estado,2);return ['estado'=>$estado,'backorder'=>$acepta];
 });}
}
